    name: string;
    about: string;
    input: string;
}[] | {
    error: string;
}>;
/** One tool's description and input schema; {error} for a name no tool has. */
declare function describeTool(name: string): Promise<{
    name: string;
    description: string;
    inputSchema: JSONSchema;
